// src/game/sfx.ts: short sound effects from public/sfx (generated by us, so no licence issues; served locally → offline-safe).
// Fire-and-forget: a blocked or missing sound never breaks the game.
import { useSettings } from "./settings";

export type SfxName = "pop" | "fizz" | "whoosh" | "correct" | "wrong";
const NAMES: SfxName[] = ["pop", "fizz", "whoosh", "correct", "wrong"];
const cache = new Map<SfxName, HTMLAudioElement>();

/** Load all sounds once (call after a user gesture, e.g. the Start button). */
export function preloadSfx() {
  if (typeof Audio === "undefined") return;
  for (const n of NAMES) {
    if (cache.has(n)) continue;
    const a = new Audio(`/sfx/${n}.wav`);
    a.preload = "auto";
    cache.set(n, a);
  }
}

export function playSfx(name: SfxName, volume = 0.6) {
  if (typeof Audio === "undefined" || !useSettings.getState().sound) return;
  try {
    const base = cache.get(name) ?? new Audio(`/sfx/${name}.wav`);
    cache.set(name, base);
    const a = base.cloneNode(true) as HTMLAudioElement; // overlapping plays
    a.volume = volume;
    void a.play().catch(() => {});
  } catch {
    /* no audio: keep playing silently */
  }
}
